<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{Order,ProductVariant}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class OrderController extends Controller {
 public function index(Request $r){return $r->user()->orders()->with('items')->latest()->paginate(10);}
 public function show(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,403); return $order->load('items');}
 public function store(Request $r){$d=$r->validate(['items'=>'required|array|min:1','items.*.product_id'=>'required|integer|exists:products,id','items.*.volume_ml'=>'required|integer|exists:product_variants,volume_ml','items.*.quantity'=>'required|integer|min:1|max:50','shipping_method'=>'required|in:post,tipax','receiver'=>'required|string|max:120','phone'=>'required|string|max:20','province'=>'required|string|max:100','city'=>'required|string|max:100','postal_code'=>'required|string|max:20','address'=>'required|string','note'=>'nullable|string|max:1000']); return DB::transaction(function() use($d,$r){$subtotal=0;$rows=[];foreach($d['items'] as $i){$v=ProductVariant::where('product_id',$i['product_id'])->where('volume_ml',$i['volume_ml'])->lockForUpdate()->firstOrFail();if($v->stock<$i['quantity'])throw ValidationException::withMessages(['items'=>'موجودی محصول کافی نیست.']);$line=$v->price*$i['quantity'];$subtotal+=$line;$rows[]=[$v,$i['quantity'],$line];$v->decrement('stock',$i['quantity']);}$shipping=$subtotal>=5000000?0:($d['shipping_method']==='post'?120000:0);$o=$r->user()->orders()->create([...$d,'tracking_code'=>'PX-'.random_int(100000,999999),'subtotal'=>$subtotal,'discount'=>0,'shipping_cost'=>$shipping,'total'=>$subtotal+$shipping]);foreach($rows as [$v,$qty,$line])$o->items()->create(['product_id'=>$v->product_id,'volume_ml'=>$v->volume_ml,'product_name'=>$v->product->name,'unit_price'=>$v->price,'quantity'=>$qty,'line_total'=>$line]);return response()->json($o->load('items'),201);});}
}
